"""Tiny DSL for authoring course content. Expected outputs are generated by
running the reference solution, so tests only list the stdin to feed."""
from textwrap import dedent

STARTER = "# Write your code below\n"


def E(title, prompt, solution, tests=None, starter=None, hints=""):
    return {"title": title, "prompt": dedent(prompt).strip(), "solution": dedent(solution).strip() + "\n",
            "tests": tests or [""], "starter": dedent(starter).lstrip("\n") if starter else STARTER,
            "hints": [h.strip() for h in hints.split("|") if h.strip()]}


def L(title, md, exercises):
    return {"title": title, "markdown": dedent(md).strip() + "\n", "exercises": exercises}


def M(title, summary, lessons, quiz):
    return {"title": title, "summary": summary, "lessons": lessons, "quiz": quiz}


def Q(q, options, answer, why):
    return {"question": q, "options": options, "answer": answer, "explanation": why}
